// Pass artwork, base64. Apple silently rejects a .pkpass missing icon.png.
//
// The card is the site's LIGHT column, so logo.png is the academix wordmark
// remapped to ink + brand red on bone; the white-on-black version vanished on
// this surface. MIX & GREET is baked in as line two because Wallet draws
// logoText to the RIGHT of the logo with no way to place it below.
//
// thumbnail.* is the fallback only — convex/wallet/serve.ts swaps in the
// headliner's photograph when the event has one, which is what makes a pass
// look like this party rather than a template.
export const PASS_IMAGES: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": "",
  "thumbnail.png": "",
  "thumbnail@2x.png": "",
  "thumbnail@3x.png": ""
};
